{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates & Options — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf8f5;--card:#fff;--muted:#6b6b6b;--accent:#7c5cff;--accent-2:#ff8273;--glass:rgba(255,255,255,0.7)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#222;background:linear-gradient(180deg,var(--bg),#f6f4f2)}
    header{padding:26px 28px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:56px;height:56px;border-radius:10px;display:grid;place-items:center;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-size:15px}
    .wrap{max-width:980px;margin:18px auto;padding:20px}
    .hero{background:var(--card);padding:26px;border-radius:14px;display:flex;gap:20px;align-items:center;box-shadow:0 8px 30px rgba(40,30,40,0.06)}
    .hero .left{flex:1}
    .hero h1{margin:0;font-size:22px}
    .hero p{color:var(--muted);margin:8px 0 0}
    .pattern{width:120px;height:120px}

    .controls{display:flex;gap:12px;margin-top:18px;align-items:center}
    .toggle{background:linear-gradient(180deg,#fff,#fbfbff);padding:6px;border-radius:999px;border:1px solid #ece8f5;display:inline-flex;align-items:center}
    .toggle button{border:0;background:transparent;padding:6px 12px;border-radius:999px;cursor:pointer;font-weight:600}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;box-shadow:0 6px 18px rgba(124,92,255,0.16)}

    .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
    .card{background:var(--card);border-radius:12px;padding:18px;border:1px solid #efeaf6;transition:transform 300ms ease,box-shadow 300ms ease}
    .card:hover{transform:translateY(-6px);box-shadow:0 18px 40px rgba(20,18,30,0.06)}
    .title{font-weight:700;margin:0}
    .price{font-size:28px;margin:8px 0;color:var(--accent)}
    .meta{color:var(--muted);font-size:14px}
    .cta-row{display:flex;justify-content:space-between;align-items:center;margin-top:12px}
    .cta{background:var(--accent);color:white;padding:8px 12px;border-radius:8px;text-decoration:none}

    .details{margin-top:22px;background:linear-gradient(90deg,rgba(124,92,255,0.03),rgba(255,130,115,0.02));padding:18px;border-radius:12px;border:1px solid rgba(124,92,255,0.06)}
    .small{font-size:13px;color:var(--muted)}

    footer{margin:28px 0;text-align:center;color:var(--muted);font-size:13px}

    /* small responsive */
    @media (max-width:880px){.cards{grid-template-columns:1fr}header{padding:14px} .hero{flex-direction:column;align-items:flex-start}}

    /* subtle svg backdrop */
    .bg-svg{position:fixed;right:-120px;top:-80px;opacity:0.08;transform:rotate(8deg);pointer-events:none}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="specialties.html">Fields</a>
      <a href="approach.html">Approach</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <svg class="bg-svg" width="480" height="480" viewBox="0 0 480 480" fill="none" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="g1" x1="0" x2="1">
        <stop offset="0" stop-color="#7c5cff" stop-opacity="0.9"/>
        <stop offset="1" stop-color="#ff8273" stop-opacity="0.9"/>
      </linearGradient>
      <pattern id="p1" x="0" y="0" width="24" height="24" patternUnits="userSpaceOnUse">
        <rect x="0" y="0" width="24" height="24" fill="transparent"/>
        <circle cx="4" cy="4" r="2" fill="#7c5cff" fill-opacity="0.12"/>
        <circle cx="20" cy="20" r="2" fill="#ff8273" fill-opacity="0.08"/>
      </pattern>
    </defs>
    <rect width="480" height="480" fill="url(#p1)"/>
    <g opacity="0.16" transform="translate(70,60)">
      <path d="M80 0c44 0 80 36 80 80s-36 80-80 80S0 124 0 80 36 0 80 0z" fill="url(#g1)" />
    </g>
  </svg>

  <main class="wrap">
    <section class="hero">
      <div class="left">
        <h1>Rates, packages, and helpful add-ons</h1>
        <p>Options are built to match how people actually make time for therapy: short focused series, monthly rhythm, or an occasional intensive. Choose what fits your life rhythm.</p>
        <div class="controls">
          <div class="toggle" role="tablist" aria-label="Pricing view">
            <button id="monthlyBtn" class="active" aria-pressed="true">Monthly</button>
            <button id="packageBtn" aria-pressed="false">Packages</button>
          </div>
          <div style="font-size:13px;color:var(--muted)">Prices animate so you can compare quickly</div>
        </div>
      </div>
      <div class="pattern">
        <svg width="120" height="120" viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
          <rect width="120" height="120" rx="18" fill="#fff" stroke="#efeaf6" />
          <g transform="translate(12,12)">
            <circle cx="24" cy="24" r="10" fill="#ff8273" opacity="0.12" />
            <rect x="52" y="16" width="42" height="18" rx="6" fill="#7c5cff" opacity="0.14" />
            <path d="M0 84c12-28 46-36 76-24" stroke="#7c5cff" stroke-opacity="0.12" stroke-width="6" fill="none" stroke-linecap="round"/>
          </g>
        </svg>
      </div>
    </section>

    <section class="cards" aria-live="polite">
      <div class="card" data-plan="starter">
        <div class="title">Starter Sessions</div>
        <div class="price" data-price>—</div>
        <div class="meta">Single sessions to explore what matters most</div>
        <div class="cta-row">
          <a class="cta" href="book.html?plan=starter" id="cta-starter">Start a session</a>
          <div class="small">30–50 minutes</div>
        </div>
      </div>

      <div class="card" data-plan="series">
        <div class="title">Focused Series</div>
        <div class="price" data-price>—</div>
        <div class="meta">3–6 session sequence for clearer shifts</div>
        <div class="cta-row">
          <a class="cta" href="book.html?plan=series" id="cta-series">Reserve a spot</a>
          <div class="small">Most people start here</div>
        </div>
      </div>

      <div class="card" data-plan="intensive">
        <div class="title">Deep-Dive Intensive</div>
        <div class="price" data-price>—</div>
        <div class="meta">A concentrated session block for focused clarity</div>
        <div class="cta-row">
          <a class="cta" href="book.html?plan=intensive" id="cta-intensive">Explore the intensive</a>
          <div class="small">90–180 minutes options</div>
        </div>
      </div>
    </section>

    <section class="details">
      <div style="display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap">
        <div style="flex:1;min-width:220px">
          <strong>Add-ons</strong>
          <p class="small">Workbooks, brief check-in messages, and specialized assessments are available as modest extras. Ask during your booking.</p>
        </div>
        <div style="flex:1;min-width:220px">
          <strong>Payment & insurance</strong>
          <p class="small">I accept private pay. If you have out-of-network benefits you may submit receipts to your insurer. I can help with codes to file claims.</p>
        </div>
        <div style="flex:1;min-width:220px">
          <strong>Cancellation & length</strong>
          <p class="small">Please notify at least 48 hours ahead if you need to cancel. Sessions are typically 50 minutes unless otherwise noted.</p>
        </div>
      </div>

      <p class="small" style="margin-top:12px">If cost is a barrier, reach out — I keep a small number of reduced-fee spaces when possible.</p>
    </section>

    <footer>
      <div>Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="margin-top:6px">Confidentiality and scope: sessions are confidential within legal and ethical limits. This practice is not a crisis service. If you're in immediate danger, please call emergency services or your local crisis line.</div>
    </footer>
  </main>

  <script>
    (function(){
      // Pricing values
      const prices = {
        monthly: {starter:95, series:160, intensive:320},
        package: {starter:90, series:880, intensive:420}
      };

      let mode = 'monthly';
      const monthlyBtn = document.getElementById('monthlyBtn');
      const packageBtn = document.getElementById('packageBtn');
      const priceEls = document.querySelectorAll('[data-price]');

      function animatePrice(el, start, end){
        const duration = 450; const startTime = performance.now();
        const fmt = (v)=> v>=1000? '$'+v.toString().replace(/\B(?=(\d{3})+(?!\d))/g,",") : '$'+v;
        requestAnimationFrame(function tick(t){
          const p = Math.min(1,(t-startTime)/duration);
          const v = Math.round(start + (end-start)*p);
          el.textContent = fmt(v) + (mode==='monthly'?'/mo':' total');
          if(p<1) requestAnimationFrame(tick);
        });
      }

      function updatePrices(){
        priceEls.forEach(el=>{
          const card = el.closest('.card');
          const plan = card.getAttribute('data-plan');
          const newVal = prices[mode][plan];
          const currentText = el.textContent.replace(/[^0-9]/g,'');
          const current = currentText?parseInt(currentText,10):0;
          animatePrice(el,current,newVal);
        });
      }

      monthlyBtn.addEventListener('click',()=>{ if(mode==='monthly') return; mode='monthly'; monthlyBtn.classList.add('active'); monthlyBtn.setAttribute('aria-pressed','true'); packageBtn.classList.remove('active'); packageBtn.setAttribute('aria-pressed','false'); updatePrices(); });
      packageBtn.addEventListener('click',()=>{ if(mode==='package') return; mode='package'; packageBtn.classList.add('active'); packageBtn.setAttribute('aria-pressed','true'); monthlyBtn.classList.remove('active'); monthlyBtn.setAttribute('aria-pressed','false'); updatePrices(); });

      // init
      updatePrices();
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffaf8;--muted:#6a6a6a;--accent:#7c5cff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#222}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 26px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(90deg,var(--accent),#ff8273);color:white;display:grid;place-items:center;font-weight:700}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:920px;margin:18px auto;padding:20px}
    .lead{background:#fff;padding:18px;border-radius:12px;border:1px solid #f0ecf8}
    h1{margin:0 0 8px;font-size:20px}
    .grid{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:18px}
    .qa{background:#fff;padding:18px;border-radius:12px;border:1px solid #f1eef8}
    .q{font-weight:700;margin:0}
    .a{color:var(--muted);margin:8px 0 18px}
    .side{background:linear-gradient(180deg,#fff,#fffaf5);padding:18px;border-radius:12px;border:1px solid #f7f2ee}
    .chip{display:inline-block;background:#fff;padding:8px 10px;border-radius:999px;border:1px solid #efe8f3;margin:6px 6px 6px 0}
    footer{margin-top:18px;text-align:center;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Fields</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <div class="lead">
      <h1>Questions people often ask</h1>
      <p style="color:var(--muted);margin:8px 0 0">Short answers to help you decide if this practice might be a good fit. If something here is unclear, please reach out by phone or email.</p>
    </div>

    <div class="grid">
      <div>
        <div class="qa">
          <p class="q">Who do you work with?</p>
          <p class="a">I work with adults navigating life transitions, relationships, and patterns of stress. Sessions are collaborative and tailored — we focus on what you want to change and what resources you already have.</p>

          <p class="q">What can I expect in a first visit?</p>
          <p class="a">The first meeting is an opportunity to describe your concerns, ask questions about approach, and try out the therapeutic fit. We'll define early goals and agree on practical next steps.</p>

          <p class="q">How long are sessions and how often?</p>
          <p class="a">Standard sessions last about 50 minutes. Frequency varies — weekly, every-other-week, or short series work, depending on goals and schedule.</p>

          <p class="q">Do you take insurance?</p>
          <p class="a">This practice operates on a private-pay basis. If you have out-of-network benefits, I can provide a receipt you can submit to your insurer. I do not bill insurance directly.</p>

          <p class="q">What if I need help right away?</p>
          <p class="a">This practice does not provide crisis services. If you are in immediate danger, please call emergency services or your local crisis line. If you're unsure where to turn, consider contacting your primary care or local crisis resources.</p>

          <p class="q">Can we meet remotely?</p>
          <p class="a">Yes. Telehealth visits are available and often work well for continuity. We will discuss privacy practices and technical needs during scheduling.</p>
        </div>
      </div>

      <aside class="side">
        <strong>Quick notes</strong>
        <div style="margin-top:8px">
          <div class="chip">Confidential within legal/ethical limits</div>
          <div class="chip">Private pay + receipts available</div>
          <div class="chip">Cancellation: 48 hours requested</div>
        </div>

        <div style="margin-top:12px">
          <strong>Boundaries & scope</strong>
          <p style="color:var(--muted);margin-top:8px">I provide psychotherapy and brief consults. I do not offer forensic evaluations, emergency crisis services, or medical management. If a referral is needed, I will help connect you with appropriate resources.</p>
        </div>

        <div style="margin-top:12px">
          <strong>Contact</strong>
          <p style="margin:8px 0 0;color:var(--muted)"><a href="mailto:{{EMAIL}}">{{EMAIL}}</a><br><a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px;background:#fff;padding:16px;border-radius:12px;border:1px solid #f1eef8">
      <h2 style="margin:0 0 10px">When therapy doesn’t fit: some practical boundaries</h2>
      <p style="color:var(--muted)">Therapy is a space for reflection and skill-building. There are times when other services are more appropriate — medical care, emergency psychiatry, or peer-run crisis services. I will be transparent if a different resource would better meet your current needs.</p>
    </section>

    <footer>
      <p style="color:var(--muted);margin-top:18px">Confidentiality note: Information you share is confidential except where disclosure is required by law (risk of harm, abuse, or court order). This site is informational and not a substitute for clinical care. If you are in acute crisis, call emergency services or your local crisis number.</p>
    </footer>
  </main>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f9fbff;--card:#fff;--muted:#6f6f6f;--accent:#7c5cff;--accent-2:#ff8273}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#222}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    .logo{width:46px;height:46px;border-radius:8px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;display:grid;place-items:center;font-weight:700}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none}
    main{max-width:920px;margin:20px auto;padding:18px}
    .intro{background:var(--card);padding:18px;border-radius:12px;border:1px solid #f1ecf8}
    h1{margin:0;font-size:22px}
    .selector{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}
    .mood{padding:10px 12px;background:#fff;border-radius:10px;border:1px solid #efe8f3;cursor:pointer}
    .mood.active{box-shadow:0 10px 30px rgba(124,92,255,0.08);border-color:transparent}
    .panel{margin-top:18px;background:linear-gradient(180deg,#fff,#fffefc);padding:18px;border-radius:12px;border:1px solid #efeaf5;display:flex;gap:18px;align-items:center}
    .panel .left{flex:1}
    .approach-name{font-weight:800;font-size:18px;margin:0}
    .approach-desc{color:var(--muted);margin:8px 0}
    .book-cta{display:inline-flex;gap:10px;align-items:center}
    .book-btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
    .secondary{background:transparent;border:1px solid #efe8f3;padding:8px 12px;border-radius:10px}

    .info{font-size:13px;color:var(--muted);margin-top:12px}

    .morph{transition:all 420ms cubic-bezier(.2,.9,.2,1)}

    @media (max-width:760px){.panel{flex-direction:column;align-items:flex-start}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">FAQ</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="intro">
      <h1>Choose how you’d like to begin</h1>
      <p style="color:var(--muted);margin-top:8px">Select the word that best fits how you feel today. The recommendation below will adjust language and the primary booking button so what you schedule feels aligned with your aim.</p>

      <div class="selector" role="tablist" aria-label="Mood selector">
        <button class="mood active" data-mood="overwhelmed">Overwhelmed</button>
        <button class="mood" data-mood="stuck">Stuck</button>
        <button class="mood" data-mood="decision">Facing a choice</button>
        <button class="mood" data-mood="growth">Want sustained change</button>
      </div>
    </section>

    <section class="panel morph" id="recommendation" aria-live="polite">
      <div class="left">
        <div class="approach-name" id="approachName">Stabilizing Session</div>
        <div class="approach-desc" id="approachDesc">A focused meeting to create immediate breathing room and a short plan that fits your current capacity.</div>
        <div class="info">Length options: 30–90 minutes. We'll tailor timing to what feels most useful.</div>
      </div>
      <div class="right" style="text-align:right">
        <div style="margin-bottom:10px;color:var(--muted)" id="ctaNote">Recommended for pressing stress</div>
        <div class="book-cta">
          <a href="{{PRIMARY_CTA_URL}}" id="primaryCta" class="book-btn">{{PRIMARY_CTA_LABEL}}</a>
          <a href="contact.html" class="secondary">Ask a question</a>
        </div>
      </div>
    </section>

    <div style="margin-top:18px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px;">
      <div style="background:#fff;padding:12px;border-radius:10px;border:1px solid #f1eef8">
        <strong>Short options</strong>
        <p style="color:var(--muted);margin:8px 0 0">One or two targeted sessions to regain footing and plan next steps.</p>
      </div>
      <div style="background:#fff;padding:12px;border-radius:10px;border:1px solid #f1eef8">
        <strong>Moderate series</strong>
        <p style="color:var(--muted);margin:8px 0 0">3–6 sessions when you want a measurable shift without open-ended commitment.</p>
      </div>
      <div style="background:#fff;padding:12px;border-radius:10px;border:1px solid #f1eef8">
        <strong>Ongoing work</strong>
        <p style="color:var(--muted);margin:8px 0 0">Regular meetings to build skills and integrate change over months.</p>
      </div>
    </div>

    <div style="margin-top:18px;background:#fff;padding:14px;border-radius:10px;border:1px solid #efeaf5">
      <strong>Confidentiality & scope</strong>
      <p style="color:var(--muted);margin-top:8px">Sessions are confidential within legal and ethical limits. This clinician does not provide emergency services; if you are in immediate danger, call emergency services or your local crisis line.</p>
    </div>

  </main>

  <script>
    (function(){
      const moods = document.querySelectorAll('.mood');
      const approachName = document.getElementById('approachName');
      const approachDesc = document.getElementById('approachDesc');
      const primaryCta = document.getElementById('primaryCta');
      const ctaNote = document.getElementById('ctaNote');

      const palette = {
        overwhelmed: {
          name: 'Stabilizing Session',
          desc: 'A focused meeting to create immediate breathing room and a short plan that fits your current capacity.',
          ctaText: 'Book a stabilizing session',
          note: 'Recommended for pressing stress',
          url: '{{PRIMARY_CTA_URL}}?focus=stabilize'
        },
        stuck: {
          name: 'Clarity Series',
          desc: 'A short sequence (3–4 meetings) to identify stuck patterns and test small changes between sessions.',
          ctaText: 'Reserve a clarity series',
          note: 'A practical path when change feels tangled',
          url: '{{PRIMARY_CTA_URL}}?focus=clarity'
        },
        decision: {
          name: 'Decision Conversation',
          desc: 'One extended session to weigh options, map values, and outline a sensible next step you can live with.',
          ctaText: 'Schedule a decision conversation',
          note: 'Helpful when a single choice matters',
          url: '{{PRIMARY_CTA_URL}}?focus=decision'
        },
        growth: {
          name: 'Sustained Support',
          desc: 'Regular sessions to build skills, practice new habits, and integrate changes into daily life.',
          ctaText: 'Start sustained support',
          note: 'A collaborative long-term rhythm',
          url: '{{PRIMARY_CTA_URL}}?focus=growth'
        }
      };

      function setActive(el){
        moods.forEach(m=>m.classList.remove('active'));
        el.classList.add('active');
      }

      function morphTo(key){
        const info = palette[key];
        // gentle animated morph: fade out, change, fade in
        const panel = document.getElementById('recommendation');
        panel.style.opacity = 0.4;
        setTimeout(()=>{
          approachName.textContent = info.name;
          approachDesc.textContent = info.desc;
          primaryCta.textContent = info.ctaText;
          primaryCta.href = info.url;
          ctaNote.textContent = info.note;
          panel.style.opacity = 1;
        },220);
      }

      moods.forEach(btn=>{
        btn.addEventListener('click',()=>{
          setActive(btn);
          morphTo(btn.getAttribute('data-mood'));
        });
      });

      // initialize from query param if present
      function paramMood(){
        try{
          const url = new URL(window.location.href);
          const m = url.searchParams.get('mood') || url.searchParams.get('focus');
          if(m && palette[m]) return m;
        }catch(e){/* ignore */}
        return null;
      }
      const preset = paramMood();
      if(preset){
        const btn = document.querySelector('.mood[data-mood="'+preset+'"]');
        if(btn){ setActive(btn); morphTo(preset); }
      } else {
        morphTo('overwhelmed');
      }

    })();
  </script>
